     1	import type { SearchableEntry } from "./settingsCatalog";
     2	
     3	export const SETTINGS_SEARCH_RESULT_LIMIT = 8;
     4	
     5	/** Lower is better, so an exact label is never buried under a description that
     6	 *  happens to mention the same word. */
     7	const MatchTier = {
     8	  exactLabel: 0,
     9	  labelPrefix: 1,
    10	  labelSubstring: 2,
    11	  breadcrumb: 3,
    12	  keyword: 4,
    13	  description: 5,
    14	} as const;
    15	
    16	type Tier = (typeof MatchTier)[keyof typeof MatchTier];
    17	
    18	const normalize = (value: string): string =>
    19	  value.toLowerCase().replace(/\s+/g, " ").trim();
    20	
    21	/** Per-node entries repeat their breadcrumb and description for every node type, so
    22	 *  matching either would bury the one relevant page under a row per type. */
    23	const isRepeated = (entry: SearchableEntry): boolean =>
    24	  entry.nodeTypeUid !== undefined;
    25	
    26	const searchableDescription = (entry: SearchableEntry): string =>
    27	  entry.kind === "setting" && !isRepeated(entry)
    28	    ? (entry.description ?? "")
    29	    : "";
    30	
    31	const haystackOf = (entry: SearchableEntry): string =>
    32	  normalize(
    33	    [
    34	      entry.label,
    35	      isRepeated(entry) ? "" : entry.breadcrumb,
    36	      ...entry.keywords,
    37	      searchableDescription(entry),
    38	    ].join(" "),
    39	  );
    40	
    41	const tierFor = (entry: SearchableEntry, query: string): Tier | null => {
    42	  const label = normalize(entry.label);
    43	  if (label === query) return MatchTier.exactLabel;
    44	  if (label.startsWith(query)) return MatchTier.labelPrefix;
    45	  if (label.includes(query)) return MatchTier.labelSubstring;
    46	  if (!isRepeated(entry) && normalize(entry.breadcrumb).includes(query))
    47	    return MatchTier.breadcrumb;
    48	  if (entry.keywords.some((keyword) => normalize(keyword).includes(query)))
    49	    return MatchTier.keyword;
    50	  const description = normalize(searchableDescription(entry));
    51	  if (description && description.includes(query)) return MatchTier.description;
    52	  return null;
    53	};
    54	
    55	/** Multi-word queries match when every word appears somewhere, but the tier still comes
    56	 *  from the whole query, so single-word precision is not diluted. */
    57	const matches = (
    58	  entry: SearchableEntry,
    59	  query: string,
    60	): { tier: Tier } | null => {
    61	  const whole = tierFor(entry, query);
    62	  if (whole !== null) return { tier: whole };
    63	
    64	  const words = query.split(" ").filter(Boolean);
    65	  if (words.length < 2) return null;
    66	  const haystack = haystackOf(entry);
    67	  return words.every((word) => haystack.includes(word))
    68	    ? { tier: MatchTier.description }
    69	    : null;
    70	};
    71	
    72	const isLabelMatch = (tier: Tier): boolean => tier <= MatchTier.labelSubstring;
    73	
    74	/** Per-node rows trail one-off rows among label matches, so a row per node type cannot
    75	 *  fill the limit ahead of a page or a one-off setting with the same word. */
    76	const isPerNodeRow = (entry: SearchableEntry): boolean =>
    77	  entry.kind === "setting" && isRepeated(entry);
    78	
    79	/** Settings before pages at the same tier; then alphabetical, for a stable list. */
    80	const compare = (
    81	  a: { entry: SearchableEntry; tier: Tier },
    82	  b: { entry: SearchableEntry; tier: Tier },
    83	): number => {
    84	  if (isLabelMatch(a.tier) !== isLabelMatch(b.tier))
    85	    return isLabelMatch(a.tier) ? -1 : 1;
    86	  if (isPerNodeRow(a.entry) !== isPerNodeRow(b.entry))
    87	    return isPerNodeRow(a.entry) ? 1 : -1;
    88	  if (a.tier !== b.tier) return a.tier - b.tier;
    89	  if (a.entry.kind !== b.entry.kind) return a.entry.kind === "setting" ? -1 : 1;
    90	  return a.entry.label.localeCompare(b.entry.label);
    91	};
    92	
    93	export const rankSettings = ({
    94	  entries,
    95	  query,
    96	  limit = SETTINGS_SEARCH_RESULT_LIMIT,
    97	}: {
    98	  entries: readonly SearchableEntry[];
    99	  query: string;
   100	  limit?: number;
   101	}): SearchableEntry[] => {
   102	  const normalized = normalize(query);
   103	  if (normalized === "") return [];
   104	  return entries
   105	    .flatMap((entry) => {
   106	      const match = matches(entry, normalized);
   107	      return match ? [{ entry, tier: match.tier }] : [];
   108	    })
   109	    .sort(compare)
   110	    .slice(0, limit)
   111	    .map(({ entry }) => entry);
   112	};
