 50	const SettingsSearchField = ({
 51	  onSelect,
 52	}: {
 53	  onSelect: (entry: SearchableEntry) => void;
 54	}): JSX.Element => {
 55	  const [query, setQuery] = useState("");
 56	  const [activeIndex, setActiveIndex] = useState(0);
 57	  const [isOpen, setIsOpen] = useState(false);
 58	  const inputRef = useRef<HTMLInputElement | null>(null);
 59	  const scrollContainerRef = useRef<HTMLDivElement | null>(null);
 60	
 61	  const results = useMemo(
 62	    () => rankSettings({ entries: buildSettingsCatalog(), query }),
 63	    [query],
 64	  );
 65	  const isShowingResults = isOpen && query.trim() !== "";
 66	
 67	  // Keeps the keyboard-selected row visible.
 68	  useEffect(() => {
 69	    const container = scrollContainerRef.current;
 70	    if (!container) return;
 71	    const activeItem = container.querySelector<HTMLElement>(
 72	      '[data-active="true"]',
 73	    );
 74	    if (!activeItem) return;
 75	    const containerRect = container.getBoundingClientRect();
 76	    const itemRect = activeItem.getBoundingClientRect();
 77	    if (
 78	      itemRect.bottom > containerRect.bottom ||
 79	      itemRect.top < containerRect.top
 80	    ) {
 81	      activeItem.scrollIntoView({ block: "nearest", behavior: "auto" });
 82	    }
 83	  }, [activeIndex, results]);
 84	
 85	  const select = (entry: SearchableEntry) => {
 86	    onSelect(entry);
 87	    setQuery("");
 88	    setIsOpen(false);
 89	    inputRef.current?.blur();
