 97	      setIsOpen(false);
 98	      return;
 99	    }
100	    if (!isShowingResults || results.length === 0) return;
101	    if (event.key === "ArrowDown") {
102	      event.preventDefault();
103	      setActiveIndex((index) => (index + 1) % results.length);
104	    } else if (event.key === "ArrowUp") {
105	      event.preventDefault();
106	      setActiveIndex((index) => (index - 1 + results.length) % results.length);
107	    } else if (event.key === "Enter") {
108	      event.preventDefault();
109	      const entry = results[activeIndex];
110	      if (entry) select(entry);
