117	      // `flip`/`preventOverflow` off: the rail is at the window edge, so Blueprint's
118	      // overflow handling pushes the list off the dialog instead of across it.
119	      position={Position.BOTTOM_LEFT}
120	      modifiers={{
121	        flip: { enabled: false },
122	        preventOverflow: { enabled: false },
123	      }}
124	      minimal={true}
125	      autoFocus={false}
126	      enforceFocus={false}
127	      fill={true}
128	      content={
129	        // Inside Menu either way, so the host theme paints the surface.
130	        <div className="max-h-80 overflow-y-auto" ref={scrollContainerRef}>
131	          <Menu className="w-96">
132	            {results.length === 0 ? (
133	              <li className="flex items-center gap-2 p-2 text-sm text-gray-500">
134	                <Icon icon="search" iconSize={12} />
135	                <span>No settings match “{query.trim()}”</span>
136	              </li>
137	            ) : (
138	              results.map((entry, index) => (
139	                <SettingsSearchResult
140	                  key={entry.id}
141	                  entry={entry}
142	                  isActive={index === activeIndex}
