152	      <div className="mx-2.5 mb-2 mt-1">
153	        <InputGroup
154	          inputRef={(input) => {
155	            inputRef.current = input;
156	          }}
157	          leftIcon="search"
158	          placeholder="Search settings"
159	          value={query}
160	          onChange={(event: React.ChangeEvent<HTMLInputElement>) => {
161	            setQuery(event.target.value);
162	            setActiveIndex(0);
163	            setIsOpen(true);
164	          }}
165	          onFocus={() => setIsOpen(true)}
166	          onBlur={() => setIsOpen(false)}
167	          onKeyDown={handleKeyDown}
168	        />
169	      </div>
170	    </Popover>
171	  );
