 48	/** Results are a portalled Popover because the tab list this field sits in is styled
 49	 *  `overflow-y: auto; overflow-x: hidden`, which clips an in-flow dropdown on both axes. */
 50	const SettingsSearchField = ({
 51	  onSelect,
 52	}: {
 53	  onSelect: (entry: SearchableEntry) => void;
 54	}): JSX.Element => {
 55	  const [query, setQuery] = useState("");
 56	  const [activeIndex, setActiveIndex] = useState(0);
 57	  const [isOpen, setIsOpen] = useState(false);
 58	  const inputRef = useRef<HTMLInputElement | null>(null);
 59	  const scrollContainerRef = useRef<HTMLDivElement | null>(null);
 60	
 61	  const results = useMemo(
 62	    () => rankSettings({ entries: buildSettingsCatalog(), query }),
 63	    [query],
 64	  );
 65	  const isShowingResults = isOpen && query.trim() !== "";
 66	
 67	  // Keeps the keyboard-selected row visible.
 68	  useEffect(() => {
 69	    const container = scrollContainerRef.current;
 70	    if (!container) return;
 71	    const activeItem = container.querySelector<HTMLElement>(
 72	      '[data-active="true"]',
 73	    );
 74	    if (!activeItem) return;
 75	    const containerRect = container.getBoundingClientRect();
 76	    const itemRect = activeItem.getBoundingClientRect();
 77	    if (
 78	      itemRect.bottom > containerRect.bottom ||
 79	      itemRect.top < containerRect.top
 80	    ) {
 81	      activeItem.scrollIntoView({ block: "nearest", behavior: "auto" });
 82	    }
 83	  }, [activeIndex, results]);
 84	
 85	  const select = (entry: SearchableEntry) => {
 86	    onSelect(entry);
 87	    setQuery("");
 88	    setIsOpen(false);
 89	    inputRef.current?.blur();
 90	  };
 91	
 92	  const handleKeyDown = (event: React.KeyboardEvent<HTMLInputElement>) => {
 93	    if (event.key === "Escape") {
 94	      // Escape clears the query instead of closing the dialog.
 95	      if (query !== "") event.stopPropagation();
 96	      setQuery("");
 97	      setIsOpen(false);
 98	      return;
 99	    }
100	    if (!isShowingResults || results.length === 0) return;
101	    if (event.key === "ArrowDown") {
102	      event.preventDefault();
103	      setActiveIndex((index) => (index + 1) % results.length);
104	    } else if (event.key === "ArrowUp") {
105	      event.preventDefault();
106	      setActiveIndex((index) => (index - 1 + results.length) % results.length);
107	    } else if (event.key === "Enter") {
108	      event.preventDefault();
109	      const entry = results[activeIndex];
110	      if (entry) select(entry);
111	    }
112	  };
113	
114	  return (
115	    <Popover
116	      isOpen={isShowingResults}
117	      // `flip`/`preventOverflow` off: the rail is at the window edge, so Blueprint's
118	      // overflow handling pushes the list off the dialog instead of across it.
119	      position={Position.BOTTOM_LEFT}
120	      modifiers={{
121	        flip: { enabled: false },
122	        preventOverflow: { enabled: false },
123	      }}
124	      minimal={true}
125	      autoFocus={false}
126	      enforceFocus={false}
127	      fill={true}
128	      content={
129	        // Inside Menu either way, so the host theme paints the surface.
130	        <div className="max-h-80 overflow-y-auto" ref={scrollContainerRef}>
131	          <Menu className="w-96">
132	            {results.length === 0 ? (
133	              <li className="flex items-center gap-2 p-2 text-sm text-gray-500">
134	                <Icon icon="search" iconSize={12} />
135	                <span>No settings match “{query.trim()}”</span>
136	              </li>
137	            ) : (
138	              results.map((entry, index) => (
139	                <SettingsSearchResult
140	                  key={entry.id}
141	                  entry={entry}
142	                  isActive={index === activeIndex}
143	                  onSelect={select}
144	                />
145	              ))
146	            )}
147	          </Menu>
148	        </div>
149	      }
150	    >
151	      {/* Inset to the tab titles' left edge. */}
152	      <div className="mx-2.5 mb-2 mt-1">
153	        <InputGroup
154	          inputRef={(input) => {
155	            inputRef.current = input;
156	          }}
157	          leftIcon="search"
158	          placeholder="Search settings"
159	          value={query}
160	          onChange={(event: React.ChangeEvent<HTMLInputElement>) => {
161	            setQuery(event.target.value);
162	            setActiveIndex(0);
163	            setIsOpen(true);
164	          }}
165	          onFocus={() => setIsOpen(true)}
166	          onBlur={() => setIsOpen(false)}
167	          onKeyDown={handleKeyDown}
168	        />
169	      </div>
170	    </Popover>
171	  );
172	};
