  6	/** `ancestorLabels` are static crumbs above the tab itself: shown in the trail, not navigable. */
  7	const SettingsPageHeader = ({
  8	  ancestorLabels,
  9	  rootLabel,
 10	  resolveLabel,
 11	  actions,
 12	}: {
