 14	  rootLabel: string;
 15	  resolveLabel: (segment: string, segmentIndex: number) => string;
 16	  actions?: React.ReactNode;
 17	}): JSX.Element | null => {
 18	  const { path, depth, pop, goToDepth } = useSettingsNav();
 19	  if (depth === 0) return null;
 20	
 21	  // depth > 0, so the trail always has a root crumb plus at least one segment.
 22	  const trail = buildBreadcrumbTrail({ path, rootLabel, resolveLabel });
 23	  const current = trail[trail.length - 1];
 24	  const parent = trail[trail.length - 2];
 25	
 26	  return (
 27	    // Shrinkable by default: without flex-shrink-0 the header squashes into the scrolling body.
 28	    <div className="mb-5 block flex-shrink-0">
 29	      <div className="mb-1 flex items-center gap-2 text-2xl font-semibold leading-tight">
 30	        <Button
 31	          minimal
 32	          small
 33	          icon="chevron-left"
 34	          title={`Back to ${parent.label}`}
 35	          aria-label={`Back to ${parent.label}`}
 36	          onClick={pop}
 37	        />
 38	        {current.label}
 39	        {actions && (
 40	          <div className="ml-auto text-sm font-normal">{actions}</div>
 41	        )}
 42	      </div>
 43	      <div className="text-sm leading-snug text-gray-500">
 44	        {ancestorLabels.map((label) => (
 45	          <span key={label}>{`${label} › `}</span>
 46	        ))}
 47	        {trail.map((crumb) => (
 48	          <span key={crumb.depth}>
 49	            {crumb.isCurrent ? (
 50	              crumb.label
 51	            ) : (
 52	              <>
 53	                <a
 54	                  className="cursor-pointer"
 55	                  onClick={() => goToDepth(crumb.depth)}
 56	                  role="button"
 57	                  tabIndex={0}
 58	                  onKeyDown={(e) => {
 59	                    if (e.key === "Enter" || e.key === " ")
 60	                      goToDepth(crumb.depth);
 61	                  }}
 62	                >
 63	                  {crumb.label}
 64	                </a>
 65	                {" › "}
 66	              </>
 67	            )}
 68	          </span>
 69	        ))}
 70	      </div>
 71	    </div>
