 24	/** Every settings key, addressed as `GROUP.member`, so the key list is never restated. */
 25	const SETTING_KEY_GROUPS = {
 26	  CANVAS_KEYS,
 27	  DISCOURSE_NODE_KEYS,
 28	  EXPORT_KEYS,
 29	  FEATURE_FLAG_KEYS,
 30	  GLOBAL_KEYS,
