 38	
 39	type SettingKeyGroups = typeof SETTING_KEY_GROUPS;
 40	
 41	export type SettingKeyId = {
 42	  [G in keyof SettingKeyGroups]: `${G & string}.${keyof SettingKeyGroups[G] & string}`;
 43	}[keyof SettingKeyGroups];
 44	
 45	const resolveKeyId = (id: SettingKeyId): string => {
 46	  const [groupName, member] = id.split(".") as [keyof SettingKeyGroups, string];
 47	  return (SETTING_KEY_GROUPS[groupName] as Record<string, string>)[member];
 48	};
