 50	/** Keys that are not a searchable row. A key must land here or in AUTHORED_SETTINGS, or it fails to compile. */
 51	type NonRowKeyId =
 52	  // Reachable only from the hidden Admin panel.
 53	  | "FEATURE_FLAG_KEYS.enableNodeSharing"
 54	  | "FEATURE_FLAG_KEYS.suggestiveModeOverlayEnabled"
 55	  | "FEATURE_FLAG_KEYS.useNewSettingsStore"
 56	  | "SUGGESTIVE_MODE_KEYS.includeCurrentPageRelations"
 57	  | "SUGGESTIVE_MODE_KEYS.includeParentAndChildBlocks"
 58	  | "SUGGESTIVE_MODE_KEYS.pageGroups"
 59	  // Containers whose children are the rows.
 60	  | "GLOBAL_KEYS.export"
 61	  | "GLOBAL_KEYS.suggestiveMode"
 62	  | "GLOBAL_KEYS.leftSidebar"
 63	  | "PERSONAL_KEYS.leftSidebar"
 64	  | "PERSONAL_KEYS.query"
 65	  | "DISCOURSE_NODE_KEYS.canvasSettings"
 66	  | "DISCOURSE_NODE_KEYS.suggestiveRules"
 67	  // Relations are configured by their own panel, not a settings row.
 68	  | "GLOBAL_KEYS.relations"
 69	  // Persisted UI state, not a setting.
 70	  | "PERSONAL_KEYS.globalSectionFolded"
 71	  // Per-section rows rendered from a list; no stable address yet.
 72	  | "LEFT_SIDEBAR_KEYS.children"
 73	  // Edited as a set by DiscourseNodeAttributes.
 74	  | "DISCOURSE_NODE_KEYS.attributes"
 75	  // Sub-controls of a row that is itself addressable.
 76	  | "CANVAS_KEYS.keyImageOption"
 77	  | "CANVAS_KEYS.queryBuilderAlias"
 78	  | "SPECIFICATION_KEYS.enabled"
 79	  | "SPECIFICATION_KEYS.query";
 80	
 81	/** Compile-time proof that every exempted id is a real key. */
 82	type AssertNonRowKeysExist = NonRowKeyId extends SettingKeyId ? true : never;
 83	const _nonRowKeysAreReal: AssertNonRowKeysExist = true;
 84	void _nonRowKeysAreReal;
 85	
 86	type RowKeyId = Exclude<SettingKeyId, NonRowKeyId>;
