 88	/** What only the call site knows. `path` is the only field a relocation touches, and is a
 89	 *  function for node-type rows so one entry expands per node type. */
 90	export type AuthoredSetting = {
 91	  /** Set when the value is nested, e.g. Export rows under `GLOBAL_KEYS.export`. */
 92	  parent?: SettingKeyId;
 93	  label: string;
 94	  group?: string;
 95	  description?: string;
 96	  docsLink?: string;
 97	  /** Synonyms plus the retired Personal/Global tab names, so users searching by the old
 98	   *  split still find a setting after the move to topic sections. */
 99	  keywords?: readonly string[];
100	  /** Omitted when the setting lives outside Settings (Export options are in the Export
101	   *  dialog): still authored for its description, but not offered by search. */
102	  path?: SettingsPath | ((nodeTypeUid: string) => SettingsPath);
103	  /** Settings a graph cannot reach are dropped rather than offered as dead ends. */
104	  isAvailable?: () => boolean;
105	};
106	
107	export type SearchableSetting = {
108	  kind: "setting";
109	  /** Unique per result; the anchor value plus the node uid for per-node rows. */
110	  id: string;
111	  anchorId: string;
112	  label: string;
113	  description?: string;
114	  keywords: readonly string[];
115	  path: SettingsPath;
116	  breadcrumb: string;
117	  /** Set on entries repeated per node type, whose shared breadcrumb is not matched. */
118	  nodeTypeUid?: string;
119	};
120	
121	export type SearchablePage = {
122	  kind: "page";
123	  id: string;
124	  label: string;
125	  keywords: readonly string[];
126	  path: SettingsPath;
127	  breadcrumb: string;
128	  nodeTypeUid?: string;
129	};
