 44	type Collapsible = { isOpen: boolean; onToggle: () => void };
 45	
 46	export const SettingsGroup = ({
 47	  title,
 48	  collapsible,
 49	  children,
 50	}: {
 51	  title: string;
 52	  collapsible?: Collapsible;
 53	  children: React.ReactNode;
 54	}): React.ReactElement => {
 55	  const contentId = useId();
 56	  const rootRef = useRef<HTMLDivElement | null>(null);
 57	  const scrollerToRealign = useRef<HTMLElement | null>(null);
 58	  const contentRef = useRef<HTMLDivElement | null>(null);
 59	  const isOpen = collapsible?.isOpen ?? true;
 60	
 61	  // Collapse only clips kept-mounted rows; inert keeps Tab out. React 18 drops an `inert` prop.
 62	  useEffect(() => {
 63	    contentRef.current?.toggleAttribute("inert", !isOpen);
 64	  }, [isOpen]);
 65	
 66	  // Collapsing a stuck section removes the content above the viewport; keep its heading in place.
 67	  // Scrolls only the settings scroller: scrollIntoView would also move Blueprint's overlay.
 68	  useLayoutEffect(() => {
 69	    const scroller = scrollerToRealign.current;
 70	    const root = rootRef.current;
 71	    scrollerToRealign.current = null;
 72	    if (!scroller || !root) return;
 73	    scroller.scrollTop +=
 74	      root.getBoundingClientRect().top - scroller.getBoundingClientRect().top;
 75	  }, [isOpen]);
 76	
 77	  const toggle = (): void => {
 78	    if (!collapsible) return;
 79	    const root = rootRef.current;
 80	    const scroller = root ? getScrollParent(root) : null;
 81	    const isStuck =
 82	      !!root &&
 83	      !!scroller &&
 84	      root.getBoundingClientRect().top < scroller.getBoundingClientRect().top;
 85	    scrollerToRealign.current = isOpen && isStuck ? scroller : null;
 86	    collapsible.onToggle();
 87	  };
 88	
 89	  return (
 90	    <div ref={rootRef} className="flex flex-col gap-1">
 91	      {collapsible ? (
 92	        <StickyHeading
 93	          className="flex cursor-pointer items-center gap-1"
 94	          role="button"
 95	          tabIndex={0}
 96	          aria-expanded={isOpen}
 97	          aria-controls={contentId}
 98	          onClick={toggle}
 99	          onKeyDown={(e) => {
100	            if ((e.key !== "Enter" && e.key !== " ") || e.repeat) return;
101	            e.preventDefault();
102	            toggle();
103	          }}
104	        >
105	          <Icon icon={isOpen ? "chevron-down" : "chevron-right"} />
106	          {title}
107	        </StickyHeading>
108	      ) : (
109	        <StickyHeading>{title}</StickyHeading>
110	      )}
111	      {collapsible ? (
112	        // keepChildrenMounted so pending setting writes and search anchors survive a collapse.
113	        <Collapse isOpen={isOpen} keepChildrenMounted>
114	          <div ref={contentRef} id={contentId} className="flex flex-col gap-4">
115	            {children}
116	          </div>
117	        </Collapse>
118	      ) : (
119	        <div className="flex flex-col gap-4">{children}</div>
120	      )}
121	    </div>
122	  );
123	};
