 61	  );
 62	  const colorWriteTimeoutRef = useRef<number | null>(null);
 63	
 64	  const persistColorValue = useCallback(
 65	    (colorValue: string): void => {
 66	      void setInputSetting({
 67	        blockUid: canvasUid,
 68	        key: "color",
 69	        value: colorValue,
 70	      });
