 80	  useEffect(() => {
 81	    return () => {
 82	      if (!colorWriteTimeoutRef.current) return;
 83	
 84	      window.clearTimeout(colorWriteTimeoutRef.current);
 85	    };
 86	  }, []);
 87	
 88	  const persistColorAfterPause = (colorValue: string): void => {
 89	    if (colorWriteTimeoutRef.current) {
 90	      window.clearTimeout(colorWriteTimeoutRef.current);
 91	      colorWriteTimeoutRef.current = null;
 92	    }
 93	    colorWriteTimeoutRef.current = window.setTimeout(() => {
 94	      persistColorValue(colorValue);
 95	      colorWriteTimeoutRef.current = null;
 96	    }, COLOR_WRITE_DEBOUNCE_MS);
 97	  };
 98	
 99	  return (
100	    <>
101	      {tagValue && (
102	        <div className="flex items-center gap-1.5 pl-1">
