149	const generateTagPlaceholder = (node: DiscourseNode): string => {
150	  // Extract first reference from format like [[CLM]], [[QUE]], [[EVD]]
151	  const referenceMatch = node.format.match(/\[\[([A-Z]+)\]\]/);
152	
153	  if (referenceMatch) {
154	    const reference = referenceMatch[1].toLowerCase();
155	    return `#${reference.slice(0, 3)}-candidate`; // [[EVD]] - {content} = #evd-candidate
156	  }
157	
158	  const nodeTextPrefix = node.text.toLowerCase().slice(0, 3);
159	  return `#${nodeTextPrefix}-candidate`; // Evidence = #evi-candidate
160	};
